	function resetObj( obj, value )
	{
		obj.hide();
		TweenLite.to( obj, 0, { alpha:0, x:0, y:0, rotation:0, scaleX:1, scaleY:1, overwrite:false });
		
	};
	
	function showObj( obj )
	{
		obj.show();
		TweenLite.to( obj, 0, { alpha:1, x:0, y:0, rotation:0, scaleX:1, scaleY:1, overwrite:false });
	};
	
	function initSettings()
	{
		//This function is used to reset the elements.
		for( i=0; i<elements.length; i++ )
		{
			resetObj(elements[i], i);
		};
		
		static_img.hide();
		alt1.hide();
		
		TweenLite.to( cover, 0, { autoAlpha:1, overwrite:false });
	};
	
	initSettings();
	
