	/************************************************************
	*************************************************************
	DISTANCE_CALCULATOR_FORMULA
	*************************************************************
	************************************************************/
	var LOCATION_CONFIRMED = false;
	var DISTANCE_ARRAY = [];
	var LOCATIONS_ARRAY = [];
	var DATES_ARRAY = [];
	var checkpoint = 0;
	
	function distance(lat1, lon1, lat2, lon2, n1, n2, loc1, dat1, distance_radius )
	{
		//INIT_VARIABLES
		var radlat1 = Math.PI * lat1/180;
		var radlat2 = Math.PI * lat2/180;
		var theta = lon1-lon2;
		var radtheta = Math.PI * theta/180;
		var dist = Math.sin(radlat1) * Math.sin(radlat2) + Math.cos(radlat1) * Math.cos(radlat2) * 		Math.cos(radtheta);
		
		//WHOLE_NUMBER_MAKER
		if (dist > 1){ dist = 1; };
		
		//DISTANCE_CALCULATION
		dist = Math.acos(dist)
		dist = dist * 180/Math.PI;
		dist = dist * 60 * 1.1515;
		
		//WE ROUND THE DISTANCE
		if( Math.round(dist) < distance_radius )
		{
			LOCATION_CONFIRMED = true;
			DISTANCE_ARRAY.push( Math.round(dist) );
			LOCATIONS_ARRAY.push( loc1 );
			DATES_ARRAY.push( dat1 );
			console.log(LOCATIONS_ARRAY);
			console.log(DATES_ARRAY);
		}else
		{
			checkpoint++;
			
			if( lat2.length == checkpoint && LOCATION_CONFIRMED == false )
			{
				console.log( distance_radius+" MILE RADIUS CHECKED - NONE" );
				/*
				static_img.show();
				*/
			};
		};
		
		//console.log("n1 is "+n1);
		//console.log("n2 is "+n2);
		if(n1 == n2-1)
		{
			/*
			VALUE 1 WILL SORT OUT WHICH LOCATION IS THE CLOSEST
			(IF THE VIEWER IS WITHIN THE RADIUS OF MULTIPLE LOCATIONS)
			
			VALUE 2 IS THE INDEX LOCATION ON THE ARRAY FOR THE
			SHORTEST DISTANCE (THIS IS NEEDED TO DISPLAY PROPER NAME OF
			THE LOCATION AND DATE)
			*/
			//-94.6 38.9
			var value1 = Math.min.apply( Math, DISTANCE_ARRAY );
			var value2 = DISTANCE_ARRAY.indexOf(value1);
			console.log("ARRAY POSITION IS "+value2);
			console.log("THE NEAREST EVENT IS "+DISTANCE_ARRAY+" MILES AWAY. "+LOCATIONS_ARRAY+" " + DATES_ARRAY);
			
			console.log( LOCATIONS_ARRAY.length );
			dynamic_location.html(LOCATIONS_ARRAY[value2]);
			dynamic_date.html(DATES_ARRAY[value2]);
			
		};
		
	};
	
